UPDATE
       TBL_BOARD_COMMENT_S SET comment_description_txt = #{commentDescriptionTxt},
       comment_modified_at_dtm = NOW() WHERE comment_sq = #{commentSq}

UPDATE
       TBL_BOARD_COMMENT_S SET comment_is_deleted_yn = 'Y' WHERE comment_sq = #{commentSq} AND
       user_sq = #{userSq}
